CREATE OR REPLACE FUNCTION public.book_appointment(_application_id uuid,_interviewer_id uuid,_starts_at timestamptz,_ends_at timestamptz,_candidate_timezone text,_meeting_link text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _id uuid; _capacity integer; _existing uuid; BEGIN PERFORM pg_advisory_xact_lock(hashtextextended(_application_id::text,0)); SELECT id INTO _existing FROM public.appointments WHERE application_id=_application_id AND status IN ('Scheduled','Confirmed') ORDER BY starts_at LIMIT 1; IF _existing IS NOT NULL THEN RETURN _existing; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(_starts_at::text,1)); SELECT max_per_slot INTO _capacity FROM public.interview_settings WHERE id=true; IF (SELECT count(*) FROM public.appointments WHERE status IN ('Scheduled','Confirmed') AND starts_at=_starts_at)>=_capacity THEN RAISE EXCEPTION 'That time is full. Please pick another slot.'; END IF; INSERT INTO public.appointments(application_id,interviewer_id,starts_at,ends_at,candidate_timezone,meeting_link) VALUES(_application_id,_interviewer_id,_starts_at,_ends_at,_candidate_timezone,_meeting_link) RETURNING id INTO _id; RETURN _id; END $$; REVOKE ALL ON FUNCTION public.book_appointment(uuid,uuid,timestamptz,timestamptz,text,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.book_appointment(uuid,uuid,timestamptz,timestamptz,text,text) TO service_role;
CREATE OR REPLACE FUNCTION public.capture_agenda_interview_segment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE delta integer; candidate_name text; BEGIN delta:=coalesce(NEW.handle_seconds,0)-coalesce(OLD.handle_seconds,0); IF OLD.timer_started_at IS NULL OR OLD.timer_active_user_id IS NULL OR delta<=0 OR delta>5400 THEN RETURN NEW; END IF; IF coalesce(to_jsonb(NEW)->>'is_test','false')='true' THEN RETURN NEW; END IF; SELECT full_name INTO candidate_name FROM public.applications WHERE id=NEW.application_id; INSERT INTO public.recruiter_agenda(user_id,title,category,starts_at,ends_at,status,source_key) VALUES(OLD.timer_active_user_id,left(coalesce(candidate_name,'Entrevista Coach'),200),'interview_coach',OLD.timer_started_at,OLD.timer_started_at+make_interval(secs=>delta),'done',TG_TABLE_NAME||':'||NEW.id||':'||OLD.timer_started_at) ON CONFLICT(source_key) DO NOTHING; RETURN NEW; END $$; REVOKE ALL ON FUNCTION public.capture_agenda_interview_segment() FROM PUBLIC,anon,authenticated;